Future<String> pranNon() async {
  await Future.delayed(Duration(seconds: 1));
  return 'Garry';
}

void main() async {
  print('Ap chaje...');
  var non = await pranNon();
  print('Bonjou $non!');
}

Stream<int> konte() async* {
  for (var i = 1; i <= 3; i++) {
    await Future.delayed(Duration(milliseconds: 500));
    yield i;
  }
}

void main() async {
  await for (var n in konte()) {
    print('Valè: $n');
  }
}

import 'dart:isolate';

int sòmLou(int n) {
  var total = 0;
  for (var i = 1; i <= n; i++) total += i;
  return total;
}

void main() async {
  var port = ReceivePort();
  await Isolate.spawn((SendPort p) {
    p.send(sòmLou(1000000));
  }, port.sendPort);
  var rezilta = await port.first;
  print('Rezilta: $rezilta');
}

extension type Metre(double valè) {
  double get anPye => valè * 3.28084;
  Metre operator +(Metre lòt) => Metre(valè + lòt.valè);
}

void main() {
  var d = Metre(2.0);
  print('${d.valè} m = ${d.anPye} pye');
  print('Total: ${(d + Metre(1.0)).valè} m');
}

